public void RenewQuest()
{
	SingletonMonoBehaviour<OcWorldManager>.Inst.InGameData.questNpcDataDic.Remove((byte)base.EmType);
	base.Condition.setCharm(isCharm: false);
	questNpcSaveData = default(QuestNpcSaveData);
	OcRand ocRand = new OcRand();
	ocRand.InitState(QuestSeed);
	int length = IslandLvToDifficultyWeights.GetLength(1);
	int islandLevel = SingletonMonoBehaviour<OcWorldManager>.Inst.IslandLevel;
	float num = 0f;
	for (int i = 0; i < length; i++)
	{
		num += IslandLvToDifficultyWeights[islandLevel, i];
	}
	float num2 = ocRand.Range(0f, num);
	float num3 = 0f;
	questNpcSaveData.SoQuestRequiredItemTableIndex = 0;
	while (questNpcSaveData.SoQuestRequiredItemTableIndex < length)
	{
		num3 += IslandLvToDifficultyWeights[islandLevel, questNpcSaveData.SoQuestRequiredItemTableIndex];
		if (num3 >= num2)
		{
			break;
		}
		questNpcSaveData.SoQuestRequiredItemTableIndex++;
	}
	SoQuestRequiredItemTable soQuestRequiredItemTable = questRequiredItemTables[questNpcSaveData.SoQuestRequiredItemTableIndex];
	float num4 = ocRand.Range(0f, soQuestRequiredItemTable.Items.Sum((IQuestRequredItemInfo info) => info.Weight));
	float num5 = 0f;
	for (int num6 = 0; num6 < soQuestRequiredItemTable.Items.Count; num6++)
	{
		IQuestRequredItemInfo questRequredItemInfo = soQuestRequiredItemTable.Items[num6];
		num5 += questRequredItemInfo.Weight;
		if (num5 >= num4)
		{
			selectedRequiredItem = questRequredItemInfo;
			questNpcSaveData.SoRequiredItemIndex = num6;
			break;
		}
	}
	float num7 = ocRand.Range(0f, soQuestRequiredItemTable.Reward.Items.Sum((SoQuestRewardTable.ItemInfo info) => info.weight));
	float num8 = 0f;
	for (int num9 = 0; num9 < soQuestRequiredItemTable.Reward.Items.Count; num9++)
	{
		SoQuestRewardTable.ItemInfo itemInfo = soQuestRequiredItemTable.Reward.Items[num9];
		num8 += itemInfo.weight;
		if (num8 >= num7)
		{
			selectedRewardItem = itemInfo;
			questNpcSaveData.SoRewardItemIndex = num9;
			break;
		}
	}
	questNpcSaveData.RequireAndRewardMultiplier = RequiredAndRewardItemMultiplier;
	questIsReceived = false;
	questNpcSaveData.QuestLimitDay = QuestStartDay + 3;
	base.Condition.setCharm(isCharm: false);
}

