public struct PlCharaInheritData
{
	[IgnoreMember]
	public string name;

	public InventoryBoxSaveData[] inheritItemList;

	[IgnoreMember]
	public InventoryBoxSaveData[] inheritPetItem;

	[IgnoreMember]
	public PetSaveData[] inheritPetList;

	[IgnoreMember]
	public floatPair[] deliveredList;

	public PlCharaInheritData(OcPlCharacterManager.OldCharaSaveStruct.OldSaveStructValue.ES3CharaSaveData oldSaveData)
	{
		name = oldSaveData.charaMakeData.Name;
		InventorySaveData inventorySaveData = oldSaveData.inventorySaveData;
		List<InventoryBoxSaveData> itemList = new List<InventoryBoxSaveData>();
		AddToItemList(inventorySaveData.equipmentList);
		AddToItemList(inventorySaveData.buildingList);
		AddToItemList(inventorySaveData.consumptionList);
		AddToItemList(inventorySaveData.materialList);
		inheritItemList = itemList.ToArray();
		List<int> list = new List<int>();
		List<InventoryBoxSaveData> list2 = new List<InventoryBoxSaveData>();
		InventoryBoxSaveData[] petList = inventorySaveData.petList;
		for (int i = 0; i < petList.Length; i++)
		{
			InventoryBoxSaveData item = petList[i];
			if (!item.itemInBox.IsNullOrEmpty())
			{
				ItemStackSaveData itemStackSaveData = item.itemInBox[0];
				if (itemStackSaveData.item.petID != 65535)
				{
					list.Add(itemStackSaveData.item.petID);
					list2.Add(item);
				}
			}
		}
		List<PetSaveData> list3 = new List<PetSaveData>();
		PetSaveData[] petSaveDatas = oldSaveData.petSaveDatas;
		for (int i = 0; i < petSaveDatas.Length; i++)
		{
			PetSaveData item2 = petSaveDatas[i];
			for (int j = 0; j < list.Count; j++)
			{
				if (item2.GUID == list[j])
				{
					item2.Reset();
					list3.Add(item2);
					list.RemoveAt(j);
					break;
				}
			}
		}
		inheritPetItem = list2.ToArray();
		inheritPetList = list3.ToArray();
		deliveredList = oldSaveData.statisticalSaveDatas.itemDelivered;
		void AddToItemList(InventoryBoxSaveData[] InventorySaveList)
		{
			for (int k = 0; k < InventorySaveList.Length; k++)
			{
				InventoryBoxSaveData item3 = InventorySaveList[k];
				ItemStackSaveData[] itemInBox = item3.itemInBox;
				for (int l = 0; l < itemInBox.Length; l++)
				{
					if (itemInBox[l].count > 0)
					{
						itemList.Add(item3);
						break;
					}
				}
			}
		}
	}
}
